    map['shop_id'] = Variable<String>(shopId);
    map['customer_profile_id'] = Variable<String>(customerProfileId);
    map['shop_name'] = Variable<String>(shopName);
    if (!nullToAbsent || businessType != null) {
      map['business_type'] = Variable<String>(businessType);
    }
    if (!nullToAbsent || shopPhone != null) {
      map['shop_phone'] = Variable<String>(shopPhone);
    }
    map['status'] = Variable<String>(status);
    map['total_billed'] = Variable<double>(totalBilled);
    map['total_paid'] = Variable<double>(totalPaid);
    map['outstanding_balance'] = Variable<double>(outstandingBalance);
    map['linked_at'] = Variable<DateTime>(linkedAt);
    if (!nullToAbsent || unlinkedAt != null) {
      map['unlinked_at'] = Variable<DateTime>(unlinkedAt);
    }
    map['updated_at'] = Variable<DateTime>(updatedAt);
    map['is_synced'] = Variable<bool>(isSynced);
    if (!nullToAbsent || syncOperationId != null) {
      map['sync_operation_id'] = Variable<String>(syncOperationId);
    }
    return map;
  }

