class CashClosingEntity extends DataClass
    implements Insertable<CashClosingEntity> {
  final String id;
  final String businessId;

  /// Date of closing (midnight timestamp)
  final DateTime closingDate;

  /// Expected cash based on transactions
  final double expectedCash;

  /// Actual cash counted
  final double actualCash;

  /// Variance (expected - actual)
  final double variance;

  /// User who performed closing
  final String closedBy;

  /// Status: MATCHED, MISMATCH_PENDING, MISMATCH_APPROVED
  final String status;

  /// Approver (if mismatch was approved)
  final String? approvedBy;

  /// Approval reason
  final String? approvalReason;

  /// Timestamps
  final DateTime createdAt;
  final DateTime? approvedAt;
  const CashClosingEntity({
    required this.id,
    required this.businessId,
    required this.closingDate,
    required this.expectedCash,
    required this.actualCash,
    required this.variance,
    required this.closedBy,
    required this.status,
    this.approvedBy,
    this.approvalReason,
    required this.createdAt,
    this.approvedAt,
  });
